import ghidra.app.script.GhidraScript;import java.nio.file.*;public class ProfileFieldRefs extends GhidraScript {public void run()throws Exception{StringBuilder b=new StringBuilder();var it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){var i=it.next();String s=i.toString();if(s.contains("-0x5f10(gp)")||s.contains("-0x5f0c(gp)")||s.contains("-0x4fd0(gp)")||s.contains("-0x4fcc(gp)")){var f=getFunctionContaining(i.getAddress());b.append(i.getAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\t"+s+"\n");}}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}
